import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Edge case: simplest possible quote ---
  it("empty item list → premium 5 G (only the processing fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(result).toEqual({ results: [{ premium: 5 }] });
  });

  // --- Base premiums for single main items (with 10% first insurance + 5 G fee) ---
  it.todo("quote for a plain sword (base 100 G) → premium 115 G (100 + 10 first insurance + 5 fee)");
  it.todo("quote for a plain amulet (base 60 G) → premium 71 G (60 + 6 first insurance + 5 fee)");
  it.todo("quote for a plain staff (base 80 G) → premium 93 G (80 + 8 first insurance + 5 fee)");
  it.todo("quote for a plain potion (base 40 G) → premium 49 G (40 + 4 first insurance + 5 fee)");

  // --- Components and the building block of 3 alike components ---
  it.todo("quote for 1 rune → base premium 25 G");
  it.todo("quote for 2 runes → base premium 50 G (no block)");
  it.todo("quote for 3 runes → base premium 60 G (block applies)");
  it.todo("quote for 4 runes → base premium 100 G (no block — block requires exactly 3)");
  it.todo("quote for 7 runes → base premium 175 G (no block — block requires exactly 3)");
  it.todo("quote for 2 runes + 1 moonstone → base premium 75 G (no block: different types)");
  it.todo("quote for 3 runes + 3 moonstones → base premium 120 G (two separate blocks)");

  // --- Item-specific modifiers in isolation ---
  it.todo("cursed sword adds a 50 % surcharge on its base premium → 150 G before policy modifiers");
  it.todo("sword with enchantment 5 adds a 30 % surcharge → 130 G before policy modifiers");
  it.todo("sword with enchantment 4 gets no high-enchantment surcharge → 100 G before policy modifiers");
  it.todo("cursed sword with enchantment 5 gets both surcharges → 180 G before policy modifiers");

  // --- Policy-wide modifiers ---
  it.todo("customer with exactly 2 years with MHPCO gets the 20 % loyalty discount");
  it.todo("customer with 1 year gets no loyalty discount");
  it.todo("the second quote in a scenario gets the 15 % follow-up contract discount");
  it.todo("the first insurance surcharge of 10 % applies to every quote, even a follow-up contract");

  // --- Modifier scope on multi-item policies ---
  it.todo("policy with a cursed sword (100 G) and a plain amulet (60 G) → 210 G before further modifiers and fee (curse adds 50 G, 50 % of the cursed sword only)");

  // --- Rounding of the premium ---
  it.todo("a premium calculation yielding 197.5 G → final premium 198 G (rounded up, MHPCO's favor)");
  it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");

  // --- Integration examples ---
  it.todo("newcomer (0 years) with a cursed sword (steel, enchantment 3) → premium 165 G");
  it.todo("long-standing customer (3 years), second quote, cursed sword (steel, enchantment 7) → premium 160 G");

  // --- Claim: standard reimbursement ---
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G (damage minus 100 G deductible)");
  it.todo("damage to a rune (insurance value 250 G), damage 200 G → payout 100 G (no special clause)");

  // --- Claim: special clauses ---
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins, then deductible)");
  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G (high-enchantment clause applies, then deductible)");

  // --- Claim: deductible per damage event ---
  it.todo("dragon attack damages a sword (500 G) and an amulet (300 G) → payout 600 G (100 G deductible per damaged item)");

  // --- Claim: rounding of the payout ---
  it.todo("a payout calculation yielding 350.5 G → final payout 350 G (rounded down, MHPCO's favor)");

  // --- Cap: insurance sum and remaining cap ---
  it.todo("policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("policy covering two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("policy covering a sword and 3 runes → insurance sum 1750 G, cap 3500 G (block discount affects the premium only)");
  it.todo("cursed sword (premium with modifiers 165 G) → cap 2000 G (premium modifiers do not raise the cap)");
  it.todo("sword insured (cap 2000 G), first claim of 1500 G → payout 1400 G, remaining cap 600 G");
  it.todo("sword insured (cap 2000 G), second successive claim of 1500 G → payout 600 G, remaining cap 0 G");

  // --- Multiple items of the same type ---
  it.todo("policy covers two swords, a dragon attack damages both → each damage entry gets its own deductible");
  it.todo("more damage entries of a type than insured (two sword damages, one sword insured) → CLI exits non-zero, claim rejected");

  // --- Error cases ---
  it.todo("quote with an unknown item type (e.g. broomstick) → CLI exits non-zero, error on stderr, no results on stdout");
  it.todo("claim referencing an item not part of the policy (amulet damaged, only a sword insured) → CLI exits non-zero with error on stderr");
  it.todo("claim referencing a damage entry with an unknown item type → CLI exits non-zero with error on stderr");
  it.todo("claim with a damage entry of amount -200 → CLI exits non-zero with error on stderr");

  // --- CLI end-to-end ---
  it.todo("CLI reads the schema example scenario from stdin and writes {results: [{premium}, {payout, remainingCap}]} to stdout");
});

