export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;

const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};

/** Premiums are rounded in the MHPCO's favour, i.e. up. */
function roundPremium(amount: number): number {
  return Math.ceil(amount);
}

const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

function policyBasePremium(items: Item[]): number {
  if (items.length === COMPONENT_BLOCK_SIZE && items.every((item) => item.type === "rune")) {
    return COMPONENT_BLOCK_PREMIUM;
  }
  return items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
}

function quotePremium(items: Item[]): number {
  const policyBase = policyBasePremium(items);
  return roundPremium(policyBase + policyBase * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE);
}

export function runScenario(scenario: Scenario): ScenarioResult {
  return {
    results: scenario.steps.map((step) => ({
      premium: quotePremium((step as QuoteStep).items),
    })),
  };
}

