const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

const DEDUCTIBLE = 100;
const CAP_FACTOR = 2;

/** Payouts are rounded in the MHPCO's favour, i.e. down. */
function roundPayout(amount: number): number {
  return Math.floor(amount);
}

interface Policy {
  items: Item[];
  remainingCap: number;
}

function insuranceSum(items: Item[]): number {
  return items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
}

function claimPayout(incident: Incident, policy: Policy): number {
  const desired = incident.damages.reduce(
    (total, damage) => total + Math.max(0, damage.amount - DEDUCTIBLE),
    0,
  );
  return roundPayout(Math.min(desired, policy.remainingCap));
}

export function runScenario(scenario: Scenario): ScenarioResult {
  const policies = new Map<number, Policy>();
  let contracts = 0;

  const results = scenario.steps.map((step, index): StepResult => {
    if (step.op === "claim") {
      const policy = policies.get(step.policy)!;
      const payout = claimPayout(step.incident, policy);
      policy.remainingCap -= payout;
      return { payout, remainingCap: policy.remainingCap };
    }

    const premium = quotePremium(step.items, scenario.customer, contracts);
    contracts += 1;
    policies.set(index, {
      items: step.items,
      remainingCap: insuranceSum(step.items) * CAP_FACTOR,
    });
    return { premium };
  });

  return { results };
}

